// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint amount, uint timeOffset) public {
        vm.assume(amount == 10 ether);
        vm.assume(timeOffset > 0);

        uint pastBefore = c.pastBlockTime();

        vm.warp(block.timestamp + timeOffset);

        (bool success, ) = address(c).call{value: amount}("");

        if (block.timestamp > pastBefore) {
            assertTrue(c.pastBlockTime() == block.timestamp);
        } else {
            assertTrue(c.pastBlockTime() == pastBefore);
        }
    }
}

